/**
 * Capture a local snapshot of real retailer listings.
 *
 *   node scripts/snapshot-retailers.mjs
 *
 * Writes `src/services/retailers/snapshot.json` from a live scrape using the
 * production parsers. Used as the offline fallback when Supabase is unconfigured
 * (or where the Edge Function has not run yet), so the UI always has real EGP
 * prices instead of an empty state.
 *
 * The snapshot is regenerated by `pnpm sync:snapshot`; it is NOT hand-edited and
 * always carries `capturedAt` so staleness is visible.
 */
import { writeFileSync } from 'node:fs';
import { RETAILERS, pageUrl } from '../supabase/functions/retailer-sync/parsers.ts';

const UA = 'NexusPCBuilderBot/1.0 (+https://nexus-pc-builder.example/bot)';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const rows = [];

for (const retailer of RETAILERS) {
  for (const target of retailer.targets) {
    // Each target may span several listing pages; page 1 is always fetched.
    const pages = Math.max(1, target.pages ?? 1);
    let fetched = 0;

    for (let page = 1; page <= pages; page += 1) {
      const url = pageUrl(target, page);
      try {
        const res = await fetch(url, {
          headers: { 'User-Agent': UA, Accept: 'text/html' },
          signal: AbortSignal.timeout(25000),
        });
        if (res.status !== 200) {
          if (page === 1) console.log(`  ${retailer.id}/${target.category}: HTTP ${res.status}`);
          break;
        }
        const products = retailer.parse(await res.text(), res.url);
        // A page with no products means we ran past the end of the listing.
        if (products.length === 0 && page > 1) break;
        fetched += products.length;
        rows.push(...products);
      } catch (error) {
        if (page === 1) console.log(`  ${retailer.id}/${target.category}: ${error.message}`);
        break;
      }
      await sleep(2000);
    }

    console.log(`  ${retailer.id}/${target.category}: ${fetched} products`);
  }
}

// De-duplicate on (retailer, externalId) — a part can appear in two categories.
const unique = new Map();
for (const row of rows) unique.set(`${row.retailerId}:${row.externalId}`, row);
const list = [...unique.values()];

const snapshot = {
  capturedAt: new Date().toISOString(),
  source: 'scripts/snapshot-retailers.mjs',
  retailers: [...new Set(list.map((r) => r.retailerId))],
  products: list,
};

writeFileSync('src/services/retailers/snapshot.json', JSON.stringify(snapshot, null, 2) + '\n');

console.log(
  `\n${list.length} products from ${snapshot.retailers.length} retailers → src/services/retailers/snapshot.json`,
);
for (const id of snapshot.retailers) {
  console.log(`   ${id}: ${list.filter((r) => r.retailerId === id).length}`);
}
